    /// <summary>
    /// The credential provider configurations for the target. These configurations specify how the gateway authenticates with the target endpoint. Constraints: • min: 1 • max: 1 (structure) The configuration for a credential provider. This structure defines how the gateway authenticates with the target endpoint. credentialProviderType -&gt; (string) [required] The type of credential provider. This field specifies which authentication method the gateway uses. Possible values: • GATEWAY_IAM_ROLE • OAUTH • API_KEY • CALLER_IAM_CREDENTIALS • JWT_PASSTHROUGH credentialProvider -&gt; (tagged union structure) The credential provider. This field contains the specific configuration for the credential provider type. NOTE: This is a Tagged Union structure. Only one of the following top level keys can be set: oauthCredentialProvider, apiKeyCredentialProvider, iamCredentialProvider. oauthCredentialProvider -&gt; (structure) The OAuth credential provider. This provider uses OAuth authentication to access the target endpoint. providerArn -&gt; (string) [required] The Amazon Resource Name (ARN) of the OAuth credential provider. This ARN identifies the provider in Amazon Web Services. Constraints: • pattern: arn:([^:]*):([^:]*):([^:]*):([0-9]{12})?:(.+) scopes -&gt; (list) [required] The OAuth scopes for the credential provider. These scopes define the level of access requested from the OAuth provider. Constraints: • min: 0 • max: 100 (string) Constraints: • min: 1 • max: 64 customParameters -&gt; (map) The custom parameters for the OAuth credential provider. These parameters provide additional configuration for the OAuth authentication process. Constraints: • min: 1 • max: 10 key -&gt; (string) Constraints: • min: 1 • max: 256 value -&gt; (string) Constraints: • min: 1 • max: 2048 grantType -&gt; (string) Specifies the kind of credentials to use for authorization: • CLIENT_CREDENTIALS - Authorization with a client ID and secret. • AUTHORIZATION_CODE - Authorization with a token that is specific to an individual end user. • TOKEN_EXCHANGE - Authorization using on-behalf-of token exchange. An inbound user token is exchanged for a downstream access token scoped to the target audience. Possible values: • CLIENT_CREDENTIALS • AUTHORIZATION_CODE • TOKEN_EXCHANGE defaultReturnUrl -&gt; (string) The URL where the end user's browser is redirected after obtaining the authorization code. Generally points to the customer's application. Constraints: • min: 1 • max: 2048 • pattern: \w+:(\/?\/?)[^\s]+ apiKeyCredentialProvider -&gt; (structure) The API key credential provider. This provider uses an API key to authenticate with the target endpoint. providerArn -&gt; (string) [required] The Amazon Resource Name (ARN) of the API key credential provider. This ARN identifies the provider in Amazon Web Services. Constraints: • pattern: arn:([^:]*):([^:]*):([^:]*):([0-9]{12})?:(.+) credentialParameterName -&gt; (string) The name of the credential parameter for the API key. This parameter name is used when sending the API key to the target endpoint. Constraints: • min: 1 • max: 64 credentialPrefix -&gt; (string) The prefix for the API key credential. This prefix is added to the API key when sending it to the target endpoint. Constraints: • min: 1 • max: 64 credentialLocation -&gt; (string) The location of the API key credential. This field specifies where in the request the API key should be placed. Possible values: • HEADER • QUERY_PARAMETER iamCredentialProvider -&gt; (structure) The IAM credential provider. This provider uses IAM authentication with SigV4 signing to access the target endpoint. service -&gt; (string) [required] The target Amazon Web Services service name used for SigV4 signing. This value identifies the service that the gateway authenticates with when making requests to the target endpoint. Constraints: • min: 1 • max: 64 • pattern: [a-zA-Z0-9._-]+ region -&gt; (string) The Amazon Web Services Region used for SigV4 signing. If not specified, defaults to the gateway's Region. Constraints: • min: 1 • max: 32 • pattern: [a-zA-Z0-9-]+ JSON Syntax: [ { "credentialProviderType": "GATEWAY_IAM_ROLE"|"OAUTH"|"API_KEY"|"CALLER_IAM_CREDENTIALS"|"JWT_PASSTHROUGH", "credentialProvider": { "oauthCredentialProvider": { "providerArn": "string", "scopes": ["string", ...], "customParameters": {"string": "string" ...}, "grantType": "CLIENT_CREDENTIALS"|"AUTHORIZATION_CODE"|"TOKEN_EXCHANGE", "defaultReturnUrl": "string" }, "apiKeyCredentialProvider": { "providerArn": "string", "credentialParameterName": "string", "credentialPrefix": "string", "credentialLocation": "HEADER"|"QUERY_PARAMETER" }, "iamCredentialProvider": { "service": "string", "region": "string" } } } ... ]
    /// </summary>
    [SecretValue]
    [CliOption("--credential-provider-configurations", GroupValues = true)]
    public IEnumerable<string>? CredentialProviderConfigurations { get; set; }

    /// <summary>
    /// Optional configuration for HTTP header and query parameter propagation to and from the gateway target. allowedRequestHeaders -&gt; (list) A list of HTTP headers that are allowed to be propagated from incoming client requests to the target. Constraints: • min: 1 • max: 10 (string) Constraints: • min: 1 • max: 100 allowedQueryParameters -&gt; (list) A list of URL query parameters that are allowed to be propagated from incoming gateway URL to the target. Constraints: • min: 1 • max: 10 (string) Constraints: • min: 1 • max: 40 allowedResponseHeaders -&gt; (list) A list of HTTP headers that are allowed to be propagated from the target response back to the client. Constraints: • min: 1 • max: 10 (string) Constraints: • min: 1 • max: 100 Shorthand Syntax: allowedRequestHeaders=string,string,allowedQueryParameters=string,string,allowedResponseHeaders=string,string JSON Syntax: { "allowedRequestHeaders": ["string", ...], "allowedQueryParameters": ["string", ...], "allowedResponseHeaders": ["string", ...] }
    /// </summary>
    [CliOption("--metadata-configuration")]
    public string? MetadataConfiguration { get; set; }

    /// <summary>
    /// The private endpoint configuration for the gateway target. Use this to connect the gateway to private resources in your VPC. NOTE: This is a Tagged Union structure. Only one of the following top level keys can be set: selfManagedLatticeResource, managedVpcResource. selfManagedLatticeResource -&gt; (tagged union structure) Configuration for connecting to a private resource using a self-managed VPC Lattice resource configuration. NOTE: This is a Tagged Union structure. Only one of the following top level keys can be set: resourceConfigurationIdentifier. resourceConfigurationIdentifier -&gt; (string) The ARN or ID of the VPC Lattice resource configuration. Constraints: • min: 20 • max: 2048 • pattern: ((rcfg-[0-9a-z]{17})|(arn:[a-z0-9\-]+:vpc-lattice:[a-zA-Z0-9\-]+:\d{12}:resourceconfiguration/rcfg-[0-9a-z]{17})) managedVpcResource -&gt; (structure) Configuration for connecting to a private resource using a managed VPC Lattice resource. The gateway creates and manages the VPC Lattice resources on your behalf. vpcIdentifier -&gt; (string) [required] The ID of the VPC that contains your private resource. Constraints: • pattern: vpc-(([0-9a-z]{8})|([0-9a-z]{17})) subnetIds -&gt; (list) [required] The subnet IDs within the VPC where the VPC Lattice resource gateway is placed. (string) Constraints: • pattern: subnet-[0-9a-zA-Z]{8,17} endpointIpAddressType -&gt; (string) [required] The IP address type for the resource configuration endpoint. Possible values: • IPV4 • IPV6 securityGroupIds -&gt; (list) The security group IDs to associate with the VPC Lattice resource gateway. If not specified, the default security group for the VPC is used. Constraints: • min: 0 • max: 5 (string) Constraints: • pattern: sg-(([0-9a-z]{8})|([0-9a-z]{17})) tags -&gt; (map) Tags to apply to the managed VPC Lattice resource gateway. Constraints: • min: 0 • max: 50 key -&gt; (string) Constraints: • min: 1 • max: 128 • pattern: [a-zA-Z0-9\s._:/=+@-]* value -&gt; (string) Constraints: • min: 0 • max: 256 • pattern: [a-zA-Z0-9\s._:/=+@-]* routingDomain -&gt; (string) An intermediate domain to use as the resource configuration endpoint instead of the actual target domain. Use this when you want to route traffic through an intermediate component such as a VPC endpoint or internal load balancer. For more information, see xref:lattice-vpc-egress-routing-domain[Route traffic through an intermediate domain]. Constraints: • min: 3 • max: 255 Shorthand Syntax: selfManagedLatticeResource={resourceConfigurationIdentifier=string},managedVpcResource={vpcIdentifier=string,subnetIds=[string,string],endpointIpAddressType=string,securityGroupIds=[string,string],tags={KeyName1=string,KeyName2=string},routingDomain=string} JSON Syntax: { "selfManagedLatticeResource": { "resourceConfigurationIdentifier": "string" }, "managedVpcResource": { "vpcIdentifier": "string", "subnetIds": ["string", ...], "endpointIpAddressType": "IPV4"|"IPV6", "securityGroupIds": ["string", ...], "tags": {"string": "string" ...}, "routingDomain": "string" } }
    /// </summary>
    [CliOption("--private-endpoint")]
    public string? PrivateEndpoint { get; set; }

    /// <summary>
    /// The private certificate authority (CA) configurations for the gateway target. Use this to have the gateway trust a private CA when it establishes TLS connections to the target endpoint. Provide each certificate by reference to an Amazon S3 object or an Amazon Web Services Secrets Manager secret. You can specify only one certificate authority configuration in this list. Constraints: • min: 1 • max: 1 (tagged union structure) A reference to a private certificate authority (CA) certificate that the gateway uses to verify TLS connections to the target endpoint. Use this when the target presents a certificate issued by a private CA that is not trusted by default. Specify exactly one certificate source. The configuration is a reference only and never contains the certificate content. NOTE: This is a Tagged Union structure. Only one of the following top level keys can be set: s3, secretsManager. s3 -&gt; (structure) The Amazon S3 location of the PEM-encoded private CA certificate. uri -&gt; (string) [required] The URI of the Amazon S3 object that contains the PEM-encoded certificate. Constraints: • pattern: s3://.{1,2043} bucketOwnerAccountId -&gt; (string) The account ID of the Amazon S3 bucket owner. This ID is used for cross-account access to the bucket. Constraints: • pattern: [0-9]{12} secretsManager -&gt; (structure) The Amazon Web Services Secrets Manager location of the PEM-encoded private CA certificate. secretArn -&gt; (string) [required] The Amazon Resource Name (ARN) of the Amazon Web Services Secrets Manager secret that contains the PEM-encoded certificate. Constraints: • pattern: arn:aws(-[^:]+)?:secretsmanager:[a-z0-9-]+:[0-9]{12}:secret:.+ Shorthand Syntax: s3={uri=string,bucketOwnerAccountId=string},secretsManager={secretArn=string} ... JSON Syntax: [ { "s3": { "uri": "string", "bucketOwnerAccountId": "string" }, "secretsManager": { "secretArn": "string" } } ... ]
    /// </summary>
    [CliOption("--certificate-configurations", GroupValues = true)]
    public IEnumerable<string>? CertificateConfigurations { get; set; }

    [CliOption("--cli-input-json")]
    public string? CliInputJson { get; set; }

    [CliOption("--generate-cli-skeleton")]
    public string? GenerateCliSkeleton { get; set; }

    /// <inheritdoc />
    IEnumerable<ValidationResult> IValidatableObject.Validate(ValidationContext validationContext)
    {
        if (_requiresAlternateInput && !(!string.IsNullOrWhiteSpace(CliInputJson) || GenerateCliSkeleton is "input" or "yaml-input"))
        {
            yield return new ValidationResult("An alternate input must remain selected for an instance created without required operation values.");
            yield break;
        }

        if (!string.IsNullOrWhiteSpace(CliInputJson) || GenerateCliSkeleton is "input" or "yaml-input")
        {
            yield break;
        }

        yield break;
    }

    /// <summary>Appends diagnostic members without exposing command option values.</summary>
    /// <param name="builder">The builder receiving the record members.</param>
    /// <returns>True because a redaction marker was appended.</returns>
    protected override bool PrintMembers(global::System.Text.StringBuilder builder)
    {
        builder.Append("Options = <redacted>");
        return true;
    }

